<?php
$number=$shipment['official_document_number']?:$shipment['transfer_number'];
$flow=$shipment['flow']??'pig';$live=$flow==='poultry_live';$goods=['pig'=>'Carcasses de porc','fish'=>'Poisson frais · '.($shipment['species_name']??''),'cattle'=>'Carcasses de bœuf','poultry'=>$shipment['item_name']??'Carcasses de volaille','poultry_live'=>'Poulets vivants'][$flow]??'Carcasses';
// Poultry is counted as well as weighed: carcasses in pieces, live birds in heads.
$count=$live?(int)$shipment['quantity_heads']:(isset($shipment['quantity_pieces'])?(int)$shipment['quantity_pieces']:null);$countLabel=$count===null?'':number_format($count,0,',',' ').' '.($live?'poulet(s) vivant(s)':'carcasse(s)');
$kind=['fish'=>'Poisson','cattle'=>'Carcasses de bœuf','poultry'=>'Carcasses de volaille','poultry_live'=>'Volailles vivantes'][$flow]??'Carcasses';
$states=['draft'=>'BROUILLON · À APPROUVER','approved'=>'APPROUVÉ · NON EXPÉDIÉ','in_transit'=>'EXPÉDIÉ · EN ROUTE','received'=>'REÇU À DESTINATION','cancelled'=>'ANNULÉ'];
$notice=['draft'=>'Document préparatoire. Cet envoi doit être approuvé avant son expédition.','approved'=>'Envoi approuvé. Le départ reste à confirmer.','in_transit'=>($flow==='fish'?'Poisson expédié':($live?'Poulets vivants expédiés':'Carcasses expédiées')).' vers la boucherie. '.($count===null?'La pesée':'Le comptage, la pesée').' d’arrivée et le contrôle sanitaire restent à effectuer.','received'=>'La réception de cet envoi a été enregistrée à destination.','cancelled'=>'Document annulé. Ne pas utiliser pour un transport.'];
$stamp=static fn($value)=>$value?date('d/m/Y à H:i',strtotime($value)):'Non renseigné';
$mass=number_format((float)$shipment['quantity_kg'],3,',',' ');
?>
